package com.example.sistema_tienda

import com.google.gson.*
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import kotlinx.coroutines.launch
import java.awt.FileDialog
import java.io.File

private fun money(value: Double) = "S/ %.2f".format(value)

@Composable fun DesktopApp() { val api = remember { DesktopApi() }; var user by remember { mutableStateOf(api.savedUser()) }; var screen by remember { mutableStateOf("dashboard") }; if (user == null) DesktopLogin(api) { user = it } else DesktopShell(api, user!!, screen) { if (it == "logout") { api.logout(); user = null } else screen = it } }

@Composable private fun DesktopLogin(api: DesktopApi, onLogin: (DesktopUser) -> Unit) { var username by remember { mutableStateOf("") }; var password by remember { mutableStateOf("") }; var host by remember { mutableStateOf(api.host) }; var error by remember { mutableStateOf<String?>(null) }; var busy by remember { mutableStateOf(false) }; val scope = rememberCoroutineScope(); Column(Modifier.fillMaxSize().padding(80.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.Center) { Text("Sistematienda", style = MaterialTheme.typography.displaySmall); Text("Iniciar sesión", style = MaterialTheme.typography.titleLarge); Spacer(Modifier.height(20.dp)); OutlinedTextField(username, { username = it }, label = { Text("Usuario") }, singleLine = true); OutlinedTextField(password, { password = it }, label = { Text("Contraseña") }, singleLine = true); OutlinedTextField(host, { host = it }, label = { Text("Servidor") }, singleLine = true); error?.let { Text(it, color = MaterialTheme.colorScheme.error) }; Row { OutlinedButton({ api.saveHost(host); scope.launch { error = runCatching { api.health(); "Servidor disponible" }.getOrElse { it.message ?: "No se pudo conectar" } } }) { Text("Probar conexión") }; Spacer(Modifier.width(8.dp)); Button(enabled = !busy && username.isNotBlank() && password.isNotBlank() && host.isNotBlank(), onClick = { api.saveHost(host); busy = true; scope.launch { runCatching { api.login(username.trim(), password) }.onSuccess { onLogin(it) }.onFailure { error = it.message }; busy = false } }) { Text(if (busy) "Ingresando…" else "Iniciar sesión") } } } }

@Composable private fun DesktopShell(api: DesktopApi, user: DesktopUser, screen: String, navigate: (String) -> Unit) { Row(Modifier.fillMaxSize()) { NavigationRail { Text("S", style = MaterialTheme.typography.headlineLarge, modifier = Modifier.padding(18.dp)); listOf("dashboard" to "Inicio", "sale" to "Nueva venta", "products" to "Productos", "merch" to "Mercadería", "sales" to if (user.rol == "admin") "Ventas" else "Mis ventas", "reports" to if (user.rol == "admin") "Reportes" else "Mis reportes").forEach { (key, label) -> NavigationRailItem(selected = screen == key, onClick = { navigate(key) }, icon = {}, label = { Text(label) }) }; if (user.rol == "admin") { NavigationRailItem(screen == "users", { navigate("users") }, icon = {}, label = { Text("Usuarios") }); NavigationRailItem(screen == "categories", { navigate("categories") }, icon = {}, label = { Text("Categorías") }) }; Spacer(Modifier.weight(1f)); NavigationRailItem(screen == "settings", { navigate("settings") }, icon = {}, label = { Text("Servidor") }); TextButton({ navigate("logout") }) { Text("Cerrar sesión") } }; Box(Modifier.fillMaxSize().padding(26.dp)) { when (screen) { "dashboard" -> DesktopDashboard(api, user, navigate); "sale" -> DesktopSale(api, user); "products" -> DesktopProducts(api); "merch" -> DesktopMerchandise(api, user); "sales" -> DesktopSales(api, user.rol == "admin"); "reports" -> DesktopReports(api); "users" -> DesktopUsers(api); "categories" -> DesktopCategories(api); "settings" -> DesktopSettings(api) } } } }

@Composable private fun DesktopDashboard(api: DesktopApi, user: DesktopUser, navigate: (String) -> Unit) { var data by remember { mutableStateOf<JsonObject?>(null) }; var error by remember { mutableStateOf<String?>(null) }; LaunchedEffect(Unit) { runCatching { api.dashboard() }.onSuccess { data = it }.onFailure { error = it.message } }; Column { Text(if (user.rol == "admin") "Dashboard" else "Mi inicio", style = MaterialTheme.typography.headlineMedium); Text("Hola, " + user.nombre); if (error != null) Text(error!!, color = MaterialTheme.colorScheme.error); if (data == null && error == null) CircularProgressIndicator(); data?.let { d -> Row(Modifier.padding(vertical = 20.dp), horizontalArrangement = Arrangement.spacedBy(12.dp)) { DesktopStat("Ventas hoy", d["ventasHoy"].asString); DesktopStat("Ingresos", money(d["ingresosHoy"].asDouble)); DesktopStat("Unidades", d["unidadesVendidasHoy"].asString); if (user.rol == "admin") DesktopStat("Stock bajo", d["productosStockBajo"].asString) }; Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) { Button({ navigate("sale") }) { Text("Nueva venta") }; OutlinedButton({ navigate("merch") }) { Text("Mercadería") }; OutlinedButton({ navigate("products") }) { Text("Productos") } } } } }
@Composable private fun DesktopStat(title: String, value: String) { Card(Modifier.width(170.dp)) { Column(Modifier.padding(18.dp)) { Text(title); Text(value, style = MaterialTheme.typography.headlineSmall) } } }

@Composable private fun DesktopProducts(api: DesktopApi) { var search by remember { mutableStateOf("") }; var list by remember { mutableStateOf<List<DesktopProduct>>(emptyList()) }; var showCreate by remember { mutableStateOf(false) }; var error by remember { mutableStateOf<String?>(null) }; val scope = rememberCoroutineScope(); fun load() { scope.launch { runCatching { api.products(search) }.onSuccess { list = it }.onFailure { error = it.message } } }; LaunchedEffect(Unit) { load() }; Column { Row(verticalAlignment = Alignment.CenterVertically) { Text("Productos", style = MaterialTheme.typography.headlineMedium); Spacer(Modifier.width(24.dp)); OutlinedTextField(search, { search = it }, label = { Text("Buscar") }); Button({ load() }) { Text("Buscar") }; Spacer(Modifier.weight(1f)); Button({ showCreate = true }) { Text("Nuevo producto") } }; error?.let { Text(it, color = MaterialTheme.colorScheme.error) }; LazyColumn { items(list) { p -> Card(Modifier.fillMaxWidth().padding(4.dp)) { Row(Modifier.padding(14.dp)) { Column(Modifier.weight(1f)) { Text(p.nombre, style = MaterialTheme.typography.titleMedium); Text(p.codigo + " · stock " + p.stock) }; Text(money(p.precioVenta)) } } } } }; if (showCreate) DesktopCreateProduct(api) { showCreate = false; load() } }
@Composable private fun DesktopCreateProduct(api: DesktopApi, close: () -> Unit) { var name by remember { mutableStateOf("") }; var code by remember { mutableStateOf("") }; var purchase by remember { mutableStateOf("") }; var sale by remember { mutableStateOf("") }; var stock by remember { mutableStateOf("") }; var image by remember { mutableStateOf<File?>(null) }; var error by remember { mutableStateOf<String?>(null) }; val scope = rememberCoroutineScope(); AlertDialog(onDismissRequest = close, title = { Text("Nuevo producto") }, text = { Column { OutlinedTextField(name, { name = it }, label = { Text("Nombre") }); OutlinedTextField(code, { code = it }, label = { Text("Código") }); OutlinedTextField(purchase, { purchase = it }, label = { Text("Precio compra") }); OutlinedTextField(sale, { sale = it }, label = { Text("Precio venta") }); OutlinedTextField(stock, { stock = it }, label = { Text("Stock") }); TextButton({ val dialog = FileDialog(null as java.awt.Frame?, "Seleccionar imagen", FileDialog.LOAD); dialog.setFilenameFilter { _, filename -> filename.lowercase().endsWith(".jpg") || filename.lowercase().endsWith(".jpeg") || filename.lowercase().endsWith(".png") || filename.lowercase().endsWith(".webp") }; dialog.setVisible(true); image = dialog.getDirectory()?.let { File(it, dialog.getFile() ?: "") } }) { Text(if (image == null) "Seleccionar imagen" else "Imagen: ${image!!.name}") }; error?.let { Text(it, color = MaterialTheme.colorScheme.error) } } }, confirmButton = { Button({ val p = purchase.toDoubleOrNull(); val s = sale.toDoubleOrNull(); val n = stock.toIntOrNull(); if (name.isBlank() || code.isBlank() || p == null || s == null || n == null || p < 0 || s < 0 || n < 0) error = "Completa los datos" else scope.launch { runCatching { val created = api.createProduct(name, code, p, s, n); image?.let { api.uploadImage(created.id, it) }; created }.onSuccess { close() }.onFailure { error = "Producto creado, pero la imagen no pudo subirse: ${it.message ?: "error"}" } } }) { Text("Guardar") } }, dismissButton = { TextButton(close) { Text("Cancelar") } }) }

@Composable private fun DesktopMerchandise(api: DesktopApi, user: DesktopUser) { var code by remember { mutableStateOf("") }; var product by remember { mutableStateOf<DesktopProduct?>(null) }; var amount by remember { mutableStateOf("1") }; var error by remember { mutableStateOf<String?>(null) }; val scope = rememberCoroutineScope(); Column { Text("Mercadería", style = MaterialTheme.typography.headlineMedium); Row { OutlinedTextField(code, { code = it }, label = { Text("Código / lector USB") }); Button({ scope.launch { runCatching { api.find(code) }.onSuccess { product = it; error = null }.onFailure { error = "Producto no registrado" } } }) { Text("Buscar") } }; Text("Enfoca el campo y presiona Enter con un lector USB."); error?.let { Text(it, color = MaterialTheme.colorScheme.error) }; product?.let { p -> Card(Modifier.padding(top = 20.dp).width(500.dp)) { Column(Modifier.padding(20.dp)) { Text(p.nombre, style = MaterialTheme.typography.titleLarge); Text("Código: " + p.codigo); Text("Stock: " + p.stock); OutlinedTextField(amount, { amount = it }, label = { Text("Cantidad") }); Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) { Button({ scope.launch { runCatching { api.increase(p.id, amount.toInt()) }.onSuccess { product = it }.onFailure { error = it.message } } }) { Text("Aumentar stock") }; if (user.rol == "admin") OutlinedButton({ scope.launch { runCatching { api.decrease(p.id, amount.toInt()) }.onSuccess { product = it }.onFailure { error = it.message } } }) { Text("Disminuir") } } } } } } }

@Composable private fun DesktopSale(api: DesktopApi, user: DesktopUser) { var code by remember { mutableStateOf("") }; var cart by remember { mutableStateOf<List<DesktopProduct>>(emptyList()) }; var error by remember { mutableStateOf<String?>(null) }; var message by remember { mutableStateOf<String?>(null) }; var busy by remember { mutableStateOf(false) }; val scope = rememberCoroutineScope(); fun add(p: DesktopProduct) { val old = cart.firstOrNull { it.id == p.id }; cart = if (old == null) cart + p.copy(stock = 1) else cart.map { if (it.id == p.id && it.stock < p.stock) it.copy(stock = it.stock + 1) else it } }; Column { Text("Nueva venta", style = MaterialTheme.typography.headlineMedium); Row { OutlinedTextField(code, { code = it }, label = { Text("Código / lector USB") }); Button({ scope.launch { runCatching { api.find(code) }.onSuccess { add(it); code = "" }.onFailure { error = "Producto no encontrado" } } }) { Text("Agregar") } }; LazyColumn(Modifier.weight(1f)) { items(cart) { p -> Row(Modifier.fillMaxWidth().padding(8.dp)) { Text(p.nombre + " × " + p.stock, Modifier.weight(1f)); Text(money(p.precioVenta * p.stock)); TextButton({ cart = cart.filterNot { it.id == p.id } }) { Text("Quitar") } } } }; Text("Total: " + money(cart.sumOf { it.precioVenta * it.stock }), style = MaterialTheme.typography.headlineSmall); error?.let { Text(it, color = MaterialTheme.colorScheme.error) }; message?.let { Text(it, color = MaterialTheme.colorScheme.primary) }; Button(enabled = cart.isNotEmpty() && !busy, onClick = { busy = true; scope.launch { runCatching { api.sell(cart.map { mapOf("productoId" to it.id, "cantidad" to it.stock) }) }.onSuccess { message = "Venta registrada #" + it["id"].asLong; cart = emptyList() }.onFailure { error = it.message }; busy = false } }) { Text(if (busy) "Registrando…" else "CONFIRMAR VENTA") } } }

@Composable private fun DesktopSales(api: DesktopApi, admin: Boolean) { var list by remember { mutableStateOf<List<DesktopSale>>(emptyList()) }; LaunchedEffect(Unit) { list = runCatching { api.sales(!admin) }.getOrDefault(emptyList()) }; Column { Text(if (admin) "Ventas" else "Mis ventas", style = MaterialTheme.typography.headlineMedium); LazyColumn { items(list) { Text("Venta #" + it.id + " · " + it.vendedor + " · " + money(it.total), Modifier.padding(10.dp)) } } } }
@Composable private fun DesktopReports(api: DesktopApi) { var report by remember { mutableStateOf<JsonObject?>(null) }; LaunchedEffect(Unit) { report = runCatching { api.report("dia") }.getOrNull() }; Column { Text("Reportes", style = MaterialTheme.typography.headlineMedium); report?.let { Text("Ventas: " + it["ventas"].asString); Text("Ingresos: " + money(it["ingresos"].asDouble)); Text("Unidades: " + it["unidadesVendidas"].asString) } ?: CircularProgressIndicator() } }
@Composable private fun DesktopUsers(api: DesktopApi) { var list by remember { mutableStateOf<JsonArray?>(null) }; var show by remember { mutableStateOf(false) }; LaunchedEffect(Unit) { list = runCatching { api.users() }.getOrNull() }; Column { Row(verticalAlignment = Alignment.CenterVertically) { Text("Usuarios", style = MaterialTheme.typography.headlineMedium); Spacer(Modifier.width(20.dp)); Button({ show = true }) { Text("Nuevo usuario") } }; list?.forEach { Text(it.asJsonObject["nombre"].asString + " · " + it.asJsonObject["username"].asString + " · " + it.asJsonObject["rol"].asString, Modifier.padding(8.dp)) } }; if (show) DesktopCreateUser(api) { show = false } }
@Composable private fun DesktopCreateUser(api: DesktopApi, close: () -> Unit) { var name by remember { mutableStateOf("") }; var username by remember { mutableStateOf("") }; var password by remember { mutableStateOf("") }; var role by remember { mutableStateOf("vendedor") }; var error by remember { mutableStateOf<String?>(null) }; val scope = rememberCoroutineScope(); AlertDialog(onDismissRequest = close, title = { Text("Nuevo usuario") }, text = { Column { OutlinedTextField(name, { name = it }, label = { Text("Nombre") }); OutlinedTextField(username, { username = it }, label = { Text("Usuario") }); OutlinedTextField(password, { password = it }, label = { Text("Contraseña") }); OutlinedTextField(role, { role = it }, label = { Text("Rol: admin o vendedor") }); error?.let { Text(it, color = MaterialTheme.colorScheme.error) } } }, confirmButton = { Button({ if (name.isBlank() || username.isBlank() || password.isBlank()) error = "Completa los datos" else scope.launch { runCatching { api.createUser(name, username, password, role) }.onSuccess { close() }.onFailure { error = it.message } } }) { Text("Guardar") } }, dismissButton = { TextButton(close) { Text("Cancelar") } }) }
@Composable private fun DesktopCategories(api: DesktopApi) { var list by remember { mutableStateOf<JsonArray?>(null) }; var show by remember { mutableStateOf(false) }; LaunchedEffect(Unit) { list = runCatching { api.categories() }.getOrNull() }; Column { Row(verticalAlignment = Alignment.CenterVertically) { Text("Categorías", style = MaterialTheme.typography.headlineMedium); Spacer(Modifier.width(20.dp)); Button({ show = true }) { Text("Nueva categoría") } }; list?.forEach { Text(it.asJsonObject["nombre"].asString, Modifier.padding(8.dp)) } }; if (show) DesktopCreateCategory(api) { show = false } }
@Composable private fun DesktopCreateCategory(api: DesktopApi, close: () -> Unit) { var name by remember { mutableStateOf("") }; var description by remember { mutableStateOf("") }; var error by remember { mutableStateOf<String?>(null) }; val scope = rememberCoroutineScope(); AlertDialog(onDismissRequest = close, title = { Text("Nueva categoría") }, text = { Column { OutlinedTextField(name, { name = it }, label = { Text("Nombre") }); OutlinedTextField(description, { description = it }, label = { Text("Descripción") }); error?.let { Text(it, color = MaterialTheme.colorScheme.error) } } }, confirmButton = { Button({ if (name.isBlank()) error = "El nombre es obligatorio" else scope.launch { runCatching { api.createCategory(name, description) }.onSuccess { close() }.onFailure { error = it.message } } }) { Text("Guardar") } }, dismissButton = { TextButton(close) { Text("Cancelar") } }) }
@Composable private fun DesktopSettings(api: DesktopApi) { var host by remember { mutableStateOf(api.host) }; var message by remember { mutableStateOf("") }; val scope = rememberCoroutineScope(); Column(Modifier.width(520.dp)) { Text("Configuración del servidor", style = MaterialTheme.typography.headlineMedium); OutlinedTextField(host, { host = it }, label = { Text("IP o host") }); Text("API: http://" + host + ":3000/api/"); Row { Button({ api.saveHost(host); scope.launch { message = runCatching { api.health(); "Servidor disponible" }.getOrElse { "No se pudo conectar: " + it.message } } }) { Text("Guardar y probar") }; Text(message, Modifier.padding(12.dp)) } } }
